const mediaKeyPattern =
  /^media\/(\d{4})\/(0[1-9]|1[0-2])\/([a-f0-9]{32}?)(?:-(thumb|medium|large|original))?\.(avif|gif|heic|heif|jpe?g|png|tiff?|webp)$/i;
const staticImagePattern = /^\/images\/[A-Za-z0-9/_-]+\.(?:avif|gif|heic|heif|jpe?g|png|tiff?|webp)$/i;
export type MediaVariant = 'thumb' | 'medium' | 'large';
type BackendVariant = MediaVariant | 'original';
type MediaVariantMap = Partial<Record<MediaVariant, string>>;

/** Frontend rendering sizes map to the exact variants generated by MediaService. */
export const MEDIA_VARIANTS: ReadonlyArray<{
  name: MediaVariant;
  backendName: BackendVariant;
  width: number;
}> = [
  { name: 'thumb', backendName: 'thumb', width: 400 },
  { name: 'medium', backendName: 'medium', width: 800 },
  { name: 'large', backendName: 'large', width: 1600 },
];

type ParsedMediaKey = { prefix: string; stem: string; variant?: BackendVariant };

function parseMediaKey(key: string): ParsedMediaKey | undefined {
  const match = mediaKeyPattern.exec(key);
  if (!match) return undefined;
  const [, year, month, stem, variant] = match;
  return {
    prefix: `media/${year}/${month}/`,
    stem,
    ...(variant ? { variant: variant.toLowerCase() as BackendVariant } : {}),
  };
}

function assetStem(key: string): string | undefined {
  const parsed = parseMediaKey(key);
  return parsed ? `${parsed.prefix}${parsed.stem}` : undefined;
}

function makeVariantKey(src: string, variant: BackendVariant): string | undefined {
  const parsed = parseMediaKey(src);
  if (!parsed) return undefined;
  return `${parsed.prefix}${parsed.stem}-${variant}.webp`;
}

function availableVariantKey(
  src: string,
  preferred: MediaVariant,
  available?: MediaVariantMap,
): string | undefined {
  if (!available) return makeVariantKey(src, MEDIA_VARIANTS.find((item) => item.name === preferred)!.backendName);

  const sourceStem = assetStem(src);
  const ranked = MEDIA_VARIANTS.filter(({ name }) => {
    const key = available[name];
    return Boolean(key && assetStem(key) === sourceStem);
  });
  if (available[preferred] && assetStem(available[preferred]) === sourceStem)
    return available[preferred];
  const largestExisting = ranked.at(-1);
  return largestExisting ? available[largestExisting.name] : src;
}

export function mediaVariantKeys(src: string, available?: MediaVariantMap): Record<MediaVariant, string> | undefined {
  if (!parseMediaKey(src)) return undefined;
  const keys = Object.fromEntries(MEDIA_VARIANTS.map(({ name }) => [
    name,
    availableVariantKey(src, name, available) ?? makeVariantKey(src, MEDIA_VARIANTS.find((item) => item.name === name)!.backendName)!,
  ])) as Record<MediaVariant, string>;
  return keys;
}

export function mediaSrcSet(src: string, available?: MediaVariantMap): string | undefined {
  const keys = mediaVariantKeys(src, available);
  if (!keys) return undefined;
  return MEDIA_VARIANTS.map(({ name, width }) => `${mediaUrl(src, keys[name])} ${width}w`).join(', ');
}

export function mediaUrl(src: string, variant?: MediaVariant | string, available?: MediaVariantMap): string {
  if (!src) return '/images/course-cover-default.webp';
  if (staticImagePattern.test(src)) return src;
  const parsed = parseMediaKey(src);
  if (!parsed) return '/images/course-cover-default.webp';

  let key = src;
  if (variant) {
    if (variant === 'thumb' || variant === 'medium' || variant === 'large') {
      key = availableVariantKey(src, variant, available)
        ?? makeVariantKey(src, MEDIA_VARIANTS.find((item) => item.name === variant)!.backendName)!;
    } else if (parseMediaKey(variant) && assetStem(variant) === assetStem(src)) {
      key = variant;
    } else {
      throw new Error('Invalid media variant key.');
    }
  }
  const base = (import.meta.env.VITE_MEDIA_BASE_URL ?? '').trim().replace(/\/+$/, '');
  if (base) return `${base}/${key}`;
  if (import.meta.env.DEV) return '/images/course-cover-default.webp';
  return `/${key}`;
}
